<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$u=current_user();$error='';$notice='';if(is_post()){verify_csrf();public_form_guard($db, 'add_funds', $_POST['recaptcha_token'] ?? '');$amount=(float)($_POST['amount']??0);$method=$_POST['method']??'';$tx=trim($_POST['transaction_id']??'');$sender=trim($_POST['sender_number']??'');$min=$config['funds']['min'];$max=$config['funds']['max'];if($amount<$min)$error='Minimum fund addition is '.money($min,'BDT').'.';elseif($amount>$max)$error='Maximum per transaction is '.money($max,'BDT').'.';elseif(!$db)$error='Database unavailable.';elseif(!in_array($method,['bkash','nagad','rocket','bank'],true))$error='Select a payment method.';else{$st=$db->prepare('INSERT INTO fund_requests(user_id,amount,method,transaction_id,sender_number) VALUES(?,?,?,?,?)');$st->execute([$u['id'],$amount,$method,$tx,$sender]);$notice='Fund request submitted for admin verification.';}}?><!doctype html><html lang="<?=e($LANG)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Account Balance — WDH</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="simple-page"><div class="breadcrumbs">Home › Client Portal › Account Balance</div><div class="dashboard-grid"><div class="dash-card"><span>Account Balance</span><strong><?=money($u['account_balance'],'BDT')?></strong></div><div class="dash-card"><span>Minimum Fund</span><strong><?=money($config['funds']['min'],'BDT')?></strong></div><div class="dash-card"><span>Maximum / Transaction</span><strong><?=money($config['funds']['max'],'BDT')?></strong></div></div><section class="auth-card" style="max-width:760px"><h2>Add Funds</h2><p class="muted">Add advance account balance for future services. Funds can later be used toward eligible purchases and renewals.</p><?php if($notice):?><div class="alert success-alert"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf_field()?><input type="text" name="website" value="" class="hp-field" tabindex="-1" autocomplete="off" aria-hidden="true"><?=recaptcha_field('add_funds')?><label>Amount (BDT)<input type="number" name="amount" min="500" max="200000" step="1" required placeholder="Minimum ৳500"></label><label>Payment Method<select name="method" required><option value="">Select method</option><option value="bkash">bKash</option><option value="nagad">Nagad</option><option value="rocket">Rocket</option><option value="bank">Bank Transfer</option></select></label><label>Transaction ID<input name="transaction_id"></label><label>Sender Number<input name="sender_number"></label><button class="btn primary">Submit Fund Request →</button></form></section></main><?php require __DIR__.'/includes/footer.php';?></body></html>
